CREATE OR REPLACE PROCEDURE sp(para_production_type_code text, para_parent_product_id integer, para_town_city text, para_login_name text) LANGUAGE plpgsql AS $$
DECLARE
    ref_cursor CURSOR FOR SELECT * FROM "Products";
    rec RECORD;
    ref_cursor2 CURSOR FOR SELECT * FROM "Customers";
    rec2 RECORD;
    matched_products integer := 0;
    matched_customers integer := 0;
BEGIN
    OPEN ref_cursor;
    LOOP
        FETCH ref_cursor INTO rec;
        EXIT WHEN NOT FOUND;
        IF {SLOT_1} THEN
            UPDATE "Products" SET "parent_product_id" = {SLOT_2} WHERE CURRENT OF ref_cursor;
            matched_products := {SLOT_3};
        END IF;
    END LOOP;
    CLOSE ref_cursor;

    IF {SLOT_4} THEN
        RAISE EXCEPTION 'No Products rows match production_type_code %', para_production_type_code;
    END IF;

    OPEN ref_cursor2;
    LOOP
        FETCH ref_cursor2 INTO rec2;
        EXIT WHEN NOT FOUND;
        IF {SLOT_5} THEN
            UPDATE "Customers" SET "login_name" = {SLOT_6} WHERE CURRENT OF ref_cursor2;
            matched_customers := {SLOT_7};
        END IF;
    END LOOP;
    CLOSE ref_cursor2;

    IF {SLOT_8} THEN
        RAISE EXCEPTION 'No Customers rows match town_city %', para_town_city;
    END IF;
END;
$$;

ledger.answer:
### {SLOT_2}

**Kind**: value

**What must go there**: the procedure parameter `para_parent_product_id`, used as the replacement value assigned to the `parent_product_id` column of the current `Products` row in the update.

### {SLOT_7}

**Kind**: assignment

**What must go there**: the current value of the customer match counter variable `matched_customers` increased by exactly one. This assigns the incremented customer match count back to `matched_customers`.

